// Общий ребёнок и одно окно на оба теста → serial.
import { BrowserContext, Page, Route } from '@playwright/test';
import { test, expect } from '../../fixtures';
import {
  annotateCleanup,
  childUrl,
  createChild,
  handoverToIntro,
  openSharedUserPage,
  qaChildName,
  readingScreens,
} from './reading.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.describe.configure({ mode: 'serial' });

// Чтение отрывков теста: GET из таблицы reading_passages (Supabase REST). TODO verify selector: адрес запроса.
const PASSAGES = /\/rest\/v1\/reading_passages(\?|$)/;

function fulfillPassages(status: number, body: string) {
  return async (route: Route) => {
    if (route.request().method() !== 'GET') return route.continue();
    await route.fulfill({ status, contentType: 'application/json', body });
  };
}

test.describe('Стартовый тест чтения — одна попытка, продолжение, сбои, 390 (autotest-writer)', () => {
  const childName = qaChildName();
  let childId = '';
  let shared: { context: BrowserContext; page: Page } | undefined;

  test.beforeAll(async ({ browser }, testInfo) => {
    shared = await openSharedUserPage(browser, testInfo, 'parent');
  });

  test.afterAll(async () => {
    await shared?.context.close();
  });

  test('Нет отрывков: «הקטעים עוד לא מוכנים» и «חזרה הביתה» @desktop @data #8bf5a8', async ({}, testInfo) => {
    const page = shared!.page;
    const s = readingScreens(page);

    // 1. Создать ребёнка, передать устройство → C1
    childId = await createChild(page, childName, '2018');
    annotateCleanup(testInfo, childName, childId);
    await handoverToIntro(page, childId, childName);

    // 2. До нажатия: отрывков нет — пустой список
    await page.route(PASSAGES, fulfillPassages(200, '[]'));

    // 3. «מתחילים!»
    await s.start.click();

    // Пустое состояние без «ошибки» (G5; AC5)
    await expect(page.getByText('הקטעים עוד לא מוכנים')).toBeVisible();
    const home = page.getByRole('button', { name: 'חזרה הביתה', exact: true }); // TODO verify selector (кнопка или ссылка)
    await expect(home).toBeVisible();
    for (const word of ['שגיאה', 'טעות']) {
      await expect(page.locator('body')).not.toContainText(word);
    }

    // 4. «חזרה הביתה» → дом ребёнка
    await home.click();
    await page.waitForURL(childUrl(childId, 'home'));
  });

  test('Ошибка сервера при загрузке отрывков: «נסה שוב» и «אחר כך» @desktop @data #8bf5a8', async ({}, testInfo) => {
    expect(childId, 'нет ребёнка из предыдущего теста (2.4)').not.toBe('');
    annotateCleanup(testInfo, childName, childId);
    const page = shared!.page;
    const s = readingScreens(page);

    // 1. Тот же ребёнок: вместо пустого списка — HTTP 500
    await page.unroute(PASSAGES);
    await page.route(PASSAGES, fulfillPassages(500, '{}'));

    // 2. Открыть C1 → «מתחילים!» или «ממשיכים!» (какая видна)
    await page.goto(`/${childId}/assessment/intro`);
    await expect(s.introTitle.or(s.resume).first()).toBeVisible();
    await s.start.or(s.resume).first().click();

    // Безопасное состояние: «נסה שוב» и «אחר כך», без «ошибки ребёнка» (AC3; G5).
    // «לא הצלחתי לשמור» при ошибке загрузки — известная находка 01.11, не проверяется.
    await expect(page.getByRole('button', { name: 'נסה שוב', exact: true })).toBeVisible();
    await expect(s.later).toBeVisible();
    for (const word of ['שגיאה', 'טעות', 'טעית']) {
      await expect(page.locator('body')).not.toContainText(word);
    }
  });
});
